export const VOLC = { x: 316, z: -306, base: 34, top: 11, h: 58 }; // cone on Ember Isle (crater rim at EMBER.y + h)
export const ARENA = { id: 'arena', name: '⚔️ Fly High Arena', x: -40, z: -330, y: 250, r: 115, floor: 200, top: 305, stand0: 122, stand1: 152, gate: PI / 2 };
export const LOBBY = { x: -40, z: -140, y: 238, r: 34 };
